<template><PageShell title="销售订单" tcode="VA01"><template #actions><el-button type="primary" @click="visible=true">创建销售订单</el-button></template><el-card><el-table :data="rows" border stripe><el-table-column prop="vbeln" label="销售订单" /><el-table-column prop="kunnr" label="客户" /><el-table-column prop="status" label="状态"><template #default="{row}"><StatusTag :value="row.status" /></template></el-table-column><el-table-column prop="totalAmount" label="金额" /><el-table-column label="操作"><template #default="{row}"><el-button link @click="show(row)">明细</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="创建销售订单" width="760px"><el-form inline><el-form-item label="客户"><el-input v-model="form.kunnr" /></el-form-item><el-form-item label="销售组织"><el-input v-model="form.vkorg" /></el-form-item></el-form><el-table :data="form.items" border><el-table-column label="物料"><template #default="{row}"><el-select v-model="row.matnr" filterable @change="price(row)"><el-option v-for="m in materials" :key="m.matnr" :label="`${m.matnr} ${m.maktx}`" :value="m.matnr" /></el-select></template></el-table-column><el-table-column label="数量"><template #default="{row}"><el-input-number v-model="row.kwmeng" :min="1" /></template></el-table-column><el-table-column label="单价"><template #default="{row}"><el-input-number v-model="row.netpr" :min="0" /></template></el-table-column></el-table><el-button class="add-line" @click="form.items.push({matnr:'M1001',kwmeng:1,netpr:45})">添加行</el-button><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">提交</el-button></template></el-dialog><el-drawer v-model="drawer" title="销售订单明细" size="60%"><pre>{{JSON.stringify(selected,null,2)}}</pre></el-drawer></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import PageShell from '../../components/PageShell.vue'; import StatusTag from '../../components/StatusTag.vue'; import { sdApi } from '../../api'; import { mmApi } from '../../api'; const rows=ref([]),visible=ref(false),drawer=ref(false),selected=ref(null),materials=ref([]),form=reactive({kunnr:'200010',vkorg:'1000',items:[{matnr:'M1001',kwmeng:1,netpr:45}]});async function load(){rows.value=await sdApi.sos()};function price(r){const m=materials.value.find(x=>x.matnr===r.matnr);if(m)r.netpr=m.stdPrice};async function save(){await sdApi.createSo(form);visible.value=false;load()};async function show(r){selected.value=await sdApi.so(r.vbeln);drawer.value=true};onMounted(async()=>{load();materials.value=(await mmApi.materials({page:1,size:100})).records||[]})
</script>
